33	    final args = call.arguments as Map<dynamic, dynamic>;
34	    switch (call.method) {
35	      case 'write':
36	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
37	        return null;
38	      case 'read':
39	        return fakeNativeStorage[args['key'] as String];
40	      case 'delete':
41	        fakeNativeStorage.remove(args['key'] as String);
42	        return null;
43	      case 'containsKey':
44	        return fakeNativeStorage.containsKey(args['key'] as String);
45	      default:
46	        return null;
47	    }
48	  }
49	
50	  setUp(() async {
51	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
52	        .setMockMethodCallHandler(secureStorageChannel, handleSecureStorageCall);
53	
54	    await resetCoreDependencies();
55	    await setupCoreDependencies();
56	  });
57	
58	  tearDown(() async {
59	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
60	        .setMockMethodCallHandler(secureStorageChannel, null);
61	    fakeNativeStorage.clear();
62	    await resetCoreDependencies();
63	  });
64	
65	  test(
66	    'exactly one get_it instance resolves Dio + FlutterSecureStorage + ApiClient',
67	    () {
68	      expect(sl.isRegistered<Dio>(), isTrue);
69	      expect(sl.isRegistered<FlutterSecureStorage>(), isTrue);
70	      expect(sl.isRegistered<ApiClient>(), isTrue);
71	
72	      // `dio` is configured through the container: both interceptors
73	      // (header + retry, AD-4/AD-5) are attached to the resolved instance,
74	      // alongside dio's own built-in default interceptor.
75	      final dio = sl<Dio>();
76	      expect(dio.interceptors.whereType<HeaderInterceptor>(), hasLength(1));
77	      expect(dio.interceptors.whereType<RetryInterceptor>(), hasLength(1));
78	
79	      // Resolving twice returns the same singleton — one container, one Dio.
80	      expect(sl<Dio>(), same(dio));
81	    },
82	  );
83	
84	  test(
85	    'setupCoreDependencies also wires the auth feature (Story 1.3) — a '
86	    'broken registration/dependency cycle must surface here, not only at '
87	    'real app launch (no device/CI exists yet to catch that otherwise)',
88	    () {
89	      expect(sl.isRegistered<AuthRemoteDataSource>(), isTrue);
90	      expect(sl.isRegistered<AuthRepository>(), isTrue);
91	      expect(sl.isRegistered<AuthCubit>(), isTrue);
92	
93	      // Actually resolves the whole chain (AuthCubit -> AuthRepository ->
94	      // AuthRemoteDataSource/AccessTokenProvider -> ApiClient/Dio) rather
95	      // than just checking the registration exists — `get_it`'s
96	      // `registerLazySingleton` only evaluates its factory on first
97	      // resolution.
98	      expect(() => sl<AuthCubit>(), returnsNormally);
99	    },
100	  );
101	
102	  test(
103	    'secure storage read/write round-trips through the DI-resolved instance',
104	    () async {
105	      final storage = sl<FlutterSecureStorage>();
106	
107	      await storage.write(key: 'spike_test_key', value: 'spike_test_value');
108	      final value = await storage.read(key: 'spike_test_key');
109	
110	      expect(value, 'spike_test_value');
111	    },
112	  );
113	}
